                    // whole-document one, which says whether the text was JSON: `JSON.parse` answers
                    // nil for text that is not, the same as for JSON `null`, so a value the session
                    // cannot hold would be declared absent and raise nothing. A refusal fails the
                    // declaration instead, which is this `<data>`'s initialization error.
                    try session.setGlobal("_scxml_seed", .string(text))
                    defer { try? session.setGlobal("_scxml_seed", .nilValue) }
                    try session.defineGlobal(
                        id,
                        as: "(function() local value, isJson = JSON._parse_document(_scxml_seed) if not isJson then error(\"the handed value is not JSON\") end return value end)()",
                        chunkName: "=seed"
                    )
                }
            } else if let expression {
                do {
                    try session.defineGlobal(id, as: expression, chunkName: "=data")
                } catch {
                    // W3C SCXML B.2: inline content that cannot be read as an expression is the
                    // string it spells, whitespace-normalized (the last of its ordered readings).
                    guard let fallback else {
                        throw error
                    }
                    try session.setGlobal(id, .string(fallback))
                }
            } else {
                try session.setGlobal(id, .nilValue)
            }
        } catch {
            raiseExecutionError(
                handed == nil
                    ? "<data id='\(id)'> expr failed to evaluate"
                    : "<data id='\(id)'> could not hold the value its parent handed it",
                engine: engine)
            _ = try? session.setGlobal(id, .nilValue)
        }
    }

    /// W3C SCXML 5.4: gives the location the value, both already lowered to Lua, and answers whether
    /// the assignment ran. A location that cannot be written, or a value that cannot be computed, is
    /// the caller's `error.execution`.
    private func assignData(_ location: String, _ value: String) -> Bool {
        executeScript("\(location) = \(value)", name: "=assign")
    }

    /// W3C SCXML 5.8: runs a chunk already lowered to Lua in the session, and answers whether it ran.
    /// A chunk that raises is the caller's `error.execution`.
    private func executeScript(_ source: String, name: String) -> Bool {
        do {
            try scriptSession.execute(source, name: name)
            return true
        } catch {
            return false
        }
    }

    /// W3C SCXML 4.7, 6.2: the text of an expression, already lowered to Lua, as ECMAScript converts a
    /// value to a string, or nil when the expression cannot be run (the caller's `error.execution`).
    /// What a `<log expr>` shows and what a `<send>`'s computed event, target and delay say.
    private func evaluateText(_ expression: String) -> String? {
        do {
            if case .string(let text) = try scriptSession.evaluate("_scxml_tostring(\(expression))", name: "=log") {
                return text
            }
            return nil
        } catch {
            return nil
        }
    }

    /// W3C SCXML 4.6: starts a `<foreach>`. The array expression, already lowered to Lua, is read once
    /// and a shallow copy is kept in a variable of the session named for the loop's nesting depth
    /// ("the array is not changed by the loop": a body that changes the variable does not change what the
    /// loop walks). Answers how many items there are, or nil when the value is not an array or cannot be
    /// read (the caller's `error.execution`).
    private func beginForeach(_ depth: Int, _ array: String) -> Int? {
        let slot = "_scxml_foreach_\(depth)"
        let copied = executeScript(
            "local source = \(array); if not _isArray(source) then error('<foreach> array is not an array') end; "
                + "local copy = {}; for i = 1, #source do copy[i] = source[i] end; \(slot) = copy",
            name: "=foreach")
        guard copied, case .integer(let count)? = try? scriptSession.evaluate("#\(slot)", name: "=foreach") else {
            return nil
        }
        return Int(count)
    }

    /// W3C SCXML 4.6: gives the `<foreach>`'s item (and, when it names one, its index) the values of one
    /// iteration, both locations already lowered to Lua. A location that cannot be written is the caller's
    /// `error.execution`.
    private func bindForeach(_ depth: Int, at position: Int, item: String, index: String?) -> Bool {
        guard executeScript("\(item) = _scxml_foreach_\(depth)[\(position + 1)]", name: "=foreach") else {
            return false
        }
        guard let index else {
            return true
        }
        return executeScript("\(index) = \(position)", name: "=foreach")
    }

    /// W3C SCXML 5.7.1, 5.6.2: the value of an expression, already lowered to Lua, as JSON text, which
    /// keeps its type: a number stays one and an object keeps its shape, so a receiver reading
    /// `_event.data.value === 42` finds 42. A value ECMAScript cannot write as JSON (`undefined`, a
    /// function) is `null`, and an expression that cannot be run is nil (the caller's `error.execution`).
    private func evaluateJSON(_ expression: String) -> String? {
        do {
            if case .string(let text) = try scriptSession.evaluate("JSON.stringify(\(expression))", name: "=value") {
                return text
            }
            return "null"
        } catch {
            return nil
        }
    }

    /// W3C SCXML 6.4.1: the value an `<invoke>` hands its child for one of its variables, read once
    /// from a Lua expression already lowered. A scalar is the value itself and anything else (an
    /// object, an array, `undefined`) is its JSON, because JSON writes `Infinity` as `null`
    /// (`LuaSeed`). An expression that cannot be run is nil (the caller's `error.execution`).
    private func evaluateSeed(_ expression: String) -> LuaSeed? {
        let session = scriptSession
        do {
            // One evaluation: an expression with a side effect (`n++`) must run once, so its value
            // is kept in a global the kind and the value are then read from.
            try session.defineGlobal("_scxml_seed_value", as: expression, chunkName: "=seed")
            defer { try? session.setGlobal("_scxml_seed_value", .nilValue) }
            let kind = try session.evaluate("type(_scxml_seed_value)", name: "=seed")
            if case .string(let name) = kind, ["boolean", "number", "string"].contains(name) {
                return .scalar(try session.evaluate("_scxml_seed_value", name: "=seed"))
            }
            if case .string(let text) = try session.evaluate("JSON.stringify(_scxml_seed_value)", name: "=seed") {
                return .json(text)
            }
            return .json("null")
        } catch {
            return nil
        }
    }

    /// W3C SCXML 5.3: declares the document's variables. Early binding runs every state's
    /// `<data>` here, at document load, before the state that holds it is visited; late binding
    /// declares a state's own on its first entry (`executeEntryActions`). Runs in the session the
    /// start established just before it (`establishScriptSession`). The order is the one
    /// §scxml-6.4 fixes for a child: the top-level `<data>`, each declared with the value the parent
    /// handed it in place of its own; the early-bound `<data>` of the states, which take none; the
    /// top-level scripts, which read the handed values; then the initial configuration is entered.
    public func initializeDataModel(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        pendingEventMetadata = EventMetadata()
        // §scxml-6.4: the values the parent handed are this start's, taken once.
        let handed = invokeSeeds
        invokeSeeds = [:]
        defineData("record", handed: handed["record"], as: "{[\"name\"] = \"whole\", [\"inner\"] = {[\"label\"] = \"inner\", [\"depth\"] = 2}, [\"list\"] = {1, 2, 3}}", engine: engine)
        defineData("listed", handed: handed["listed"], as: "\"handed listed\"", engine: engine)
        defineData("stray", handed: handed["stray"], as: "\"handed stray\"", engine: engine)
        defineData("raising_seen", handed: handed["raising_seen"], as: "\"\"", engine: engine)
        defineData("effectful_seen", handed: handed["effectful_seen"], as: "\"\"", engine: engine)
        defineData("effects_seen", handed: handed["effects_seen"], as: "(-1)", engine: engine)
        defineData("refusable_seen", handed: handed["refusable_seen"], as: "\"\"", engine: engine)
        defineData("kept_seen", handed: handed["kept_seen"], as: "\"\"", engine: engine)
        defineData("stranger_seen", handed: handed["stranger_seen"], as: "\"\"", engine: engine)
        defineData("payload_seen", handed: handed["payload_seen"], as: "\"\"", engine: engine)
        defineData("script_seen", handed: handed["script_seen"], as: "\"\"", engine: engine)
        defineData("entry_seen", handed: handed["entry_seen"], as: "\"\"", engine: engine)
        defineData("errors_seen", handed: handed["errors_seen"], as: "(-1)", engine: engine)
        defineData("listed_seen", handed: handed["listed_seen"], as: "\"\"", engine: engine)
        defineData("stray_seen", handed: handed["stray_seen"], as: "\"\"", engine: engine)
        defineData("record_seen", handed: handed["record_seen"], as: "\"\"", engine: engine)
        defineData("list_errors_seen", handed: handed["list_errors_seen"], as: "(-1)", engine: engine)
    }

    /// Keeps the metadata of the event about to be selected on (§scxml-5.10).
    public func populateEventMetadata(_ metadata: EventMetadata) {
        pendingEventMetadata = metadata
    }

    /// W3C SCXML 5.10: binds the event whose transitions are about to be selected as the `_event`
    /// their guards read, whole, so a field it does not carry is absent. The null event is an
    /// eventless selection, which has no event of its own, so `_event` stays what it was.
    public func bindCurrentEvent(_ event: AChildTakesAHandedValueInPlaceOfItsDataEvent, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        guard event != .null else {
            return
        }
        let metadata = pendingEventMetadata
        let name = metadata.name.isEmpty ? getEventName(event) : metadata.name
        do {
            let reading = try scriptSession.bindCurrentEvent(
                LuaEvent(
                    name: name,
                    type: metadata.eventType.description,
                    sendID: metadata.sendID,
                    // W3C SCXML 5.10.1 + C.1 (docs/adr/0090): `_event.origin` and
                    // `_event.origintype` are the two fields of the one pair the delivering
                    // processor wrote where it built the event, read here as they are: for an
                    // event a session sent, the location the sender published (test 336). An
                    // event no processor stamped hands both over as the empty text, which the
                    // binding leaves blank: undefined to the document, never `''`.
                    origin: metadata.originAddress,
                    originType: metadata.originProcessor,
                    invokeID: metadata.invokeID,
                    data: metadata.data
                ))
            // W3C SCXML B.2.8.1: which rung the payload got is known only here, where the ladder was
            // climbed, so the engine is told now. One a host sent as structure and the datamodel
            // refused is the reading the engine counts (`Engine.undecodablePayloads`); without
            // this call the payload is lost to the document and to the host alike.
            engine.notePayloadReading(event, reading: Self.payloadReading(of: reading))
        } catch {
            raiseExecutionError("_event could not be bound for '\(name)'", engine: engine)
        }
    }

    /// The engine's name for a rung the script engine reports: the two modules each declare the
    /// five readings, since the script engine does not depend on the runtime.
    private static func payloadReading(of reading: SceLua.PayloadReading) -> SceRuntime.PayloadReading {
        switch reading {
        case .absent: return .absent
        case .dom: return .dom
        case .structured: return .structured
        case .text: return .text
        case .undecodable: return .undecodable
        }
    }

    /// W3C SCXML 5.9.1: a `cond` that cannot be evaluated is false, and raises `error.execution`.
    private func evaluateGuard(_ condition: String, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) -> Bool {
        var failed = false
        return evaluateCond(condition, of: "<transition>", failed: &failed, engine: engine)
    }

    /// W3C SCXML 4.3, 5.9.1: the same for the `cond` of an `<if>` or `<elseif>`, which also says that
    /// it failed, because the element that held it ends its block once the chain has run (§scxml-4.9).
    private func evaluateIfCond(_ condition: String, failed: inout Bool, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) -> Bool {
        evaluateCond(condition, of: "<if>", failed: &failed, engine: engine)
    }

    private func evaluateCond(
        _ condition: String,
        of element: String,
        failed: inout Bool,
        engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>
    ) -> Bool {
        do {
            return try scriptSession.evaluateCondition(condition, chunkName: "=cond")
        } catch {
            raiseExecutionError("a \(element) cond failed to evaluate", engine: engine)
            failed = true
            return false
        }
    }


    // ------------------------------------------------------------------
    // Child sessions (W3C SCXML 6.4)
    // ------------------------------------------------------------------

    /// W3C SCXML 6.4: the `<invoke>`s a state's entry deferred to the end of the
    /// macrostep. A state exited before then drops its own.
    private var pendingInvokes: [PendingInvoke<AChildTakesAHandedValueInPlaceOfItsDataState>] = []

    /// W3C SCXML 6.4.1: the invocations running, by the id their `<invoke>` carries.
    private var activeInvokes: [String: ChildSession] = [:]

    /// The session `<invoke>` `by_namelist` started, while its state is active.
    private var sceInvokeChildByNamelist: InvokedSession<AChildTakesAHandedValueInPlaceOfItsDataSceSynthInvokeByNamelistPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneByNamelist = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsByNamelist = 0

    /// The session `<invoke>` `by_param` started, while its state is active.
    private var sceInvokeChildByParam: InvokedSession<AChildTakesAHandedValueInPlaceOfItsDataSceSynthInvokeByParamPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneByParam = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsByParam = 0

    /// The session `<invoke>` `first_macrostep` started, while its state is active.
    private var sceInvokeChildFirstMacrostep: InvokedSession<AChildTakesAHandedValueInPlaceOfItsDataSceSynthInvokeFirstMacrostepPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneFirstMacrostep = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsFirstMacrostep = 0

    /// The session `<invoke>` `late_bound` started, while its state is active.
    private var sceInvokeChildLateBound: InvokedSession<AChildTakesAHandedValueInPlaceOfItsDataSceSynthInvokeLateBoundPolicy>?

    /// Whether that session has ended and `done.invoke` was raised for it: once.
    private var sceInvokeDoneLateBound = false

    /// How many times that `<invoke>` has started: each start's id is told apart by it.
    private var sceInvokeStartsLateBound = 0

    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("by_namelist".utf8) {
                sceStartInvokeByNamelist(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("by_param".utf8) {
                sceStartInvokeByParam(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("first_macrostep".utf8) {
                sceStartInvokeFirstMacrostep(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("late_bound".utf8) {
                sceStartInvokeLateBound(pending, engine: engine)
                return
            }
        }
    }

    /// Starts the session of `<invoke>` `by_namelist` (W3C SCXML 6.4).
    private func sceStartInvokeByNamelist(_ pending: PendingInvoke<AChildTakesAHandedValueInPlaceOfItsDataState>, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        // W3C SCXML C.1: the child is known by the id its parent mints for it and
        // keys the invocation on, so the sender of what it sends is the id it
        // publishes in `_ioprocessors`.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let childPolicy = AChildTakesAHandedValueInPlaceOfItsDataSceSynthInvokeByNamelistPolicy()
#if DEBUG
        // docs/adr/0096: a test that fails this session's steps on request fails the child's too.
        childPolicy.sceScriptSessionFault = sceScriptSessionFault
#endif
        // W3C SCXML 6.4.1: the child is handed the values this invoke names before it
        // initializes.
        var seeds: [String: LuaSeed] = [:]
        if let seedValue = evaluateSeed("listed") {
            seeds["listed"] = seedValue
        } else {
            raiseExecutionError("<invoke> namelist entry 'listed' could not be read", engine: engine)
        }
        if let seedValue = evaluateSeed("stray") {
            seeds["stray"] = seedValue
        } else {
            raiseExecutionError("<invoke> namelist entry 'stray' could not be read", engine: engine)
        }
        if let seedValue = evaluateSeed("record") {
            seeds["record"] = seedValue
        } else {
            raiseExecutionError("<invoke> namelist entry 'record' could not be read", engine: engine)
        }
        childPolicy.acceptSeeds(seeds)

        let session = InvokedSession(
            policy: childPolicy,
            sessionID: childSessionID,
            queue: ParentEventQueue(parentSessionID: sessionID)
        )
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["by_namelist"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "by_namelist",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        // W3C SCXML 6.4: the child's delayed sends are measured on this machine's
        // clock, so a delay on either side of the boundary is the same instant and a
        // clock its host advances moves the child too.
        session.engine.setClock(engine.clock())
        // SCE_MESH.md §21.3: the child's router is the one the factory answers for this invoke
        // and this document (empty for a child written in line), installed before the child
        // initializes, since its first state may already send.
        engine.startChildMesh(of: session, invokeID: "by_namelist", document: documentStem("#a_child_takes_a_handed_value_in_place_of_its_data__sce_synth_invoke__by_namelist"))
        guard startChildSession(session, invokeID: "by_namelist", engine: engine) else {
            // docs/adr/0096: the child's start was refused, so the invoke ends without a child:
            // it is not kept, and `startChildSession` raised the error.execution that says so.
            activeInvokes["by_namelist"] = nil
            return
        }
        sceInvokeChildByNamelist = session
        // W3C SCXML 6.4: what the child sent while it initialized, and whether it
        // ended doing so.
        sceSettleInvokeByNamelist(engine: engine)
    }

    /// Takes what the session of `<invoke>` `by_namelist` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeByNamelist(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        guard let child = sceInvokeChildByNamelist, !sceInvokeDoneByNamelist else {
            return
        }
        drainAndRaiseChildEvents(
            childEngine: child,
            activeInvokes: activeInvokes,
            invokeKey: "by_namelist",
            engine: engine
        )
        if child.isInFinalState {
            sceInvokeDoneByNamelist = true
            // SCE_MESH.md §21.5: the session reached its top-level `<final>`, so its router
            // is told once.
            child.detachMesh()
            raiseDoneInvoke(invokeID: "by_namelist", donedata: child.donedataAtFinal, engine: engine)
        }
    }

    /// Starts the session of `<invoke>` `by_param` (W3C SCXML 6.4).
