    /// top-level `<final>` stashed).
    private func sceSettleInvokeByParam(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        guard let child = sceInvokeChildByParam, !sceInvokeDoneByParam else {
