        engine.startChildMesh(of: session, invokeID: "first_macrostep", document: documentStem("#a_child_takes_a_handed_value_in_place_of_its_data__sce_synth_invoke__first_macrostep"))
        guard startChildSession(session, invokeID: "first_macrostep", engine: engine) else {
