        // W3C SCXML 6.4: what the child sent while it initialized, and whether it
        // ended doing so.
        sceSettleInvokeFirstMacrostep(engine: engine)
    }

    /// Takes what the session of `<invoke>` `first_macrostep` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeFirstMacrostep(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        guard let child = sceInvokeChildFirstMacrostep, !sceInvokeDoneFirstMacrostep else {
            return
        }
        drainAndRaiseChildEvents(
            childEngine: child,
            activeInvokes: activeInvokes,
            invokeKey: "first_macrostep",
            engine: engine
        )
        if child.isInFinalState {
            sceInvokeDoneFirstMacrostep = true
            // SCE_MESH.md §21.5: the session reached its top-level `<final>`, so its router
            // is told once.
            child.detachMesh()
            raiseDoneInvoke(invokeID: "first_macrostep", donedata: child.donedataAtFinal, engine: engine)
        }
    }

    /// Starts the session of `<invoke>` `late_bound` (W3C SCXML 6.4).
    private func sceStartInvokeLateBound(_ pending: PendingInvoke<AChildTakesAHandedValueInPlaceOfItsDataState>, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        // W3C SCXML C.1: the child is known by the id its parent mints for it and
        // keys the invocation on, so the sender of what it sends is the id it
        // publishes in `_ioprocessors`.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let childPolicy = AChildTakesAHandedValueInPlaceOfItsDataSceSynthInvokeLateBoundPolicy()
#if DEBUG
        // docs/adr/0096: a test that fails this session's steps on request fails the child's too.
        childPolicy.sceScriptSessionFault = sceScriptSessionFault
#endif
        // W3C SCXML 6.4.1: the child is handed the values this invoke names before it
        // initializes.
        var seeds: [String: LuaSeed] = [:]
        seeds["handed"] = .scalar(.string("handed late"))
        seeds["kept"] = .scalar(.string("handed kept"))
        childPolicy.acceptSeeds(seeds)

        let session = InvokedSession(
            policy: childPolicy,
            sessionID: childSessionID,
            queue: ParentEventQueue(parentSessionID: sessionID)
        )
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["late_bound"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "late_bound",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        // W3C SCXML 6.4: the child's delayed sends are measured on this machine's
        // clock, so a delay on either side of the boundary is the same instant and a
        // clock its host advances moves the child too.
        session.engine.setClock(engine.clock())
        // SCE_MESH.md §21.3: the child's router is the one the factory answers for this invoke
        // and this document (empty for a child written in line), installed before the child
        // initializes, since its first state may already send.
        engine.startChildMesh(of: session, invokeID: "late_bound", document: documentStem("#a_child_takes_a_handed_value_in_place_of_its_data__sce_synth_invoke__late_bound"))
        guard startChildSession(session, invokeID: "late_bound", engine: engine) else {
            // docs/adr/0096: the child's start was refused, so the invoke ends without a child:
            // it is not kept, and `startChildSession` raised the error.execution that says so.
            activeInvokes["late_bound"] = nil
            return
        }
        sceInvokeChildLateBound = session
        // W3C SCXML 6.4: what the child sent while it initialized, and whether it
        // ended doing so.
        sceSettleInvokeLateBound(engine: engine)
    }

    /// Takes what the session of `<invoke>` `late_bound` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeLateBound(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        guard let child = sceInvokeChildLateBound, !sceInvokeDoneLateBound else {
