    /// Ticks the running sessions (W3C SCXML 6.4): what a child sent before is taken
    /// first, then the child takes its turn, then what it sent in it.
    public func tickChildren(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        if !sceInvokeDoneByNamelist, let child = sceInvokeChildByNamelist {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "by_namelist",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeByNamelist(engine: engine)
        }
        if !sceInvokeDoneByParam, let child = sceInvokeChildByParam {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "by_param",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeByParam(engine: engine)
        }
        if !sceInvokeDoneFirstMacrostep, let child = sceInvokeChildFirstMacrostep {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "first_macrostep",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeFirstMacrostep(engine: engine)
        }
        if !sceInvokeDoneLateBound, let child = sceInvokeChildLateBound {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "late_bound",
                engine: engine
            )
            child.applyMeshCalls()
            child.tick()
            sceSettleInvokeLateBound(engine: engine)
        }
    }

    /// Settles what every running child sent this machine while a delivery drove it
    /// (docs/adr/0045): one body for every drive of a child, so a save at any boundary
    /// of this session finds its buffer empty.
    public func settleChildren(engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>) {
        sceSettleInvokeByNamelist(engine: engine)
        sceSettleInvokeByParam(engine: engine)
        sceSettleInvokeFirstMacrostep(engine: engine)
        sceSettleInvokeLateBound(engine: engine)
    }

    /// The nearest deadline of a running child (W3C SCXML 6.4), so a host that walks
    /// time by `timeUntilNextScheduled` does not step over a timer a child armed. A
    /// child that has ended is skipped: the policy keeps it until its state exits, and
    /// what it armed is no longer owed.
    public func nextChildDeadline() -> Duration? {
        var soonest: Duration?
        if !sceInvokeDoneByNamelist, let due = sceInvokeChildByNamelist?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneByParam, let due = sceInvokeChildByParam?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneFirstMacrostep, let due = sceInvokeChildFirstMacrostep?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneLateBound, let due = sceInvokeChildLateBound?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        return soonest
    }

    /// Delivers a delayed `<send target="#_<invokeid>">` whose wait is over, by name:
    /// a child need not declare every event its parent sends (W3C SCXML 6.2 + 6.4).
    /// Whether the invocation was there to take it: one whose session has reached its
    /// final state has ended, and the engine reports the send it could not deliver
    /// (W3C SCXML C.1).
    public func deliverToInvocation(invokeID: String, eventName: String, eventData: String, sendID: String) -> Bool {
        if invokeID.utf8.elementsEqual("by_namelist".utf8) {
            if let child = sceInvokeChildByNamelist, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("by_param".utf8) {
            if let child = sceInvokeChildByParam, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("first_macrostep".utf8) {
            if let child = sceInvokeChildFirstMacrostep, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("late_bound".utf8) {
            if let child = sceInvokeChildLateBound, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("by_namelist".utf8) {
            return sceInvokeChildByNamelist.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("by_param".utf8) {
            return sceInvokeChildByParam.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("first_macrostep".utf8) {
            return sceInvokeChildFirstMacrostep.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("late_bound".utf8) {
            return sceInvokeChildLateBound.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["by_namelist"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildByNamelist.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["by_param"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildByParam.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["first_macrostep"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildFirstMacrostep.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["late_bound"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildLateBound.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["by_namelist"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildByNamelist {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        if let session = activeInvokes["by_param"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildByParam {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        if let session = activeInvokes["first_macrostep"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildFirstMacrostep {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        if let session = activeInvokes["late_bound"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildLateBound {
            deliverToChild(child, eventName: eventName, eventData: eventData, sender: sessionID)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: AChildTakesAHandedValueInPlaceOfItsDataState, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .byNamelist:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsByNamelist += 1
                let generatedInvokeID = "byNamelist.\(sceInvokeStartsByNamelist).by_namelist"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .byNamelist,
                    documentID: "by_namelist"
                ))
            }
        case .byParam:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsByParam += 1
                let generatedInvokeID = "byParam.\(sceInvokeStartsByParam).by_param"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .byParam,
                    documentID: "by_param"
                ))
            }
        case .firstMacrostep:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsFirstMacrostep += 1
                let generatedInvokeID = "firstMacrostep.\(sceInvokeStartsFirstMacrostep).first_macrostep"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .firstMacrostep,
                    documentID: "first_macrostep"
                ))
            }
        case .lateBound:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsLateBound += 1
                let generatedInvokeID = "lateBound.\(sceInvokeStartsLateBound).late_bound"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .lateBound,
                    documentID: "late_bound"
                ))
            }
        default:
            break  // No entry actions
        }
    }

