    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: AChildTakesAHandedValueInPlaceOfItsDataState, engine: Engine<AChildTakesAHandedValueInPlaceOfItsDataPolicy>, configurationBeforeExit: [AChildTakesAHandedValueInPlaceOfItsDataState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .byNamelist:
            cancelInvokesForState(&pendingInvokes, .byNamelist)
            sceInvokeChildByNamelist?.stop()
            sceInvokeChildByNamelist?.detachMesh()
            sceInvokeChildByNamelist = nil
            activeInvokes["by_namelist"] = nil
            sceInvokeDoneByNamelist = false
        case .byParam:
            cancelInvokesForState(&pendingInvokes, .byParam)
            sceInvokeChildByParam?.stop()
            sceInvokeChildByParam?.detachMesh()
            sceInvokeChildByParam = nil
            activeInvokes["by_param"] = nil
            sceInvokeDoneByParam = false
        case .firstMacrostep:
            cancelInvokesForState(&pendingInvokes, .firstMacrostep)
            sceInvokeChildFirstMacrostep?.stop()
            sceInvokeChildFirstMacrostep?.detachMesh()
            sceInvokeChildFirstMacrostep = nil
            activeInvokes["first_macrostep"] = nil
            sceInvokeDoneFirstMacrostep = false
        case .lateBound:
            cancelInvokesForState(&pendingInvokes, .lateBound)
            sceInvokeChildLateBound?.stop()
            sceInvokeChildLateBound?.detachMesh()
            sceInvokeChildLateBound = nil
            activeInvokes["late_bound"] = nil
            sceInvokeDoneLateBound = false
        default:
            break  // No invocations to cancel
        }
    }



